import pandas as pd
P={'7701':'Phase-3','7703':'Phase-3','7704':'Phase-2','7702':'Phase-1'}
tot={}
for s,ph in P.items():
    sl=pd.read_csv(f'{ph}/03-DATASETS/klv-{s}-adsl.csv'); ae=pd.read_csv(f'{ph}/03-DATASETS/klv-{s}-ae.csv')
    ae=ae.merge(sl[['USUBJID','TRT01A']],on='USUBJID')
    print('\n==',s, sl.TRT01A.value_counts().to_dict(), 'median dur',sl.groupby('TRT01A').TRTDURD.median().to_dict(), 'max',sl.TRTDURD.max())
    for t,cond in [('MDS',ae.AEDECOD.isin(['Myelodysplastic syndrome','Acute myeloid leukaemia'])),('Pneu',ae.AEDECOD=='Pneumonitis'),('SevAn',(ae.AEDECOD=='Anaemia')&(ae.AETOXGR>=3))]:
        d=ae[cond]
        for arm,g in d.groupby('TRT01A'):
            r=(g.USUBJID.nunique(), g[g.AETOXGR>=3].USUBJID.nunique(), g[g.AESER=='Y'].USUBJID.nunique(), g[g.AETOXGR==5].USUBJID.nunique(), g.groupby('USUBJID').AESTDY.min().median())
            print(t,arm,r)
            key=(t,'pl' if 'lacebo' in arm else 'kv'); a=tot.get(key,(0,0,0,0)); tot[key]=tuple(x+y for x,y in zip(a,r[:4]))
print(tot)
EOF

